export function packExtractionBatches(units: ExtractionUnit[], maxContextChars: number, maxItems = Number.POSITIVE_INFINITY): ExtractionUnit[][] {
  const batches: ExtractionUnit[][] = []
  let batch: ExtractionUnit[] = [], chars = 0
  for (const unit of units) {
    if (batch.length && (chars + stableJson(unit).length > maxContextChars * 0.7 || batch.length >= maxItems)) {
      batches.push(batch); batch = []; chars = 0
    }
    batch.push(unit); chars += stableJson(unit).length
  }
  return batches
}
